// Card pool for the !cards game — REAL Shoob cards (shoob.gg).
// Generated by scripts/gen-shoob-cards.py from CardKami's data:
//   shoob.js  — 139 real Shoob cards: cdn.shoob.gg image + shoob.gg page each
//   stands.js — LEGENDS roster: name, series, stats (grades E..SSS = 1..8)
// Power = sum of the six stat grades (6-48). Rarity by power rank:
//   top 3 Legendary, next 11 Epic, next 28 Rare, rest Common.
// Pack odds stay 70/20/8/2 Common/Rare/Epic/Legendary per slot.
// No invented cards: the old 36-card original pool is gone for good.

export type Rarity = 'Common' | 'Rare' | 'Epic' | 'Legendary'

export interface CardDef {
  id: string
  name: string
  series: string
  img: string   // cdn.shoob.gg card art
  page: string  // shoob.gg card page (credit)
  rarity: Rarity
  power: number
}

export const RARITY_EMOJI: Record<Rarity, string> = {
  Common: '⚪',
  Rare: '🔵',
  Epic: '🟣',
  Legendary: '🟡'
}

